import React from 'react';
import { Link } from 'react-router-dom'; // If using react-router-dom

export default function SplineEmbed() {
  return (
    <div className="relative w-full h-screen overflow-hidden">
      {/* Spline 3D Embed */}
      <iframe
        src="https://my.spline.design/cubes-A0T7CP5J2qsawolli9BlhInB/"
        className="w-full h-full border-0"
        title="3D Cubes Scene"
      />

      {/* Gradient Shadow Overlay */}
      <div className="absolute inset-0 pointer-events-none">
        {/* Main gradient overlay */}
        <div
          className="absolute inset-0"
          style={{
            background: `
              linear-gradient(
                180deg,
                rgba(0, 188, 212, 0.3) 0%,
                rgba(0, 150, 180, 0.4) 25%,
                rgba(0, 100, 120, 0.6) 50%,
                rgba(0, 50, 70, 0.8) 75%,
                rgba(0, 20, 30, 0.9) 100%
              )
            `,
          }}
        />
        {/* Additional atmospheric depth */}
        <div
          className="absolute inset-0"
          style={{
            background: `
              radial-gradient(
                ellipse at center bottom,
                rgba(0, 0, 0, 0.4) 0%,
                rgba(0, 0, 0, 0.2) 40%,
                transparent 70%
              )
            `,
          }}
        />
        {/* Subtle vignette effect */}
        <div
          className="absolute inset-0"
          style={{
            background: `
              radial-gradient(
                ellipse at center,
                transparent 30%,
                rgba(0, 0, 0, 0.1) 70%,
                rgba(0, 0, 0, 0.3) 100%
              )
            `,
          }}
        />
        {/* Bottom shadow effect */}
        <div
          className="absolute bottom-0 left-0 right-0 h-1/3"
          style={{
            background: `
              linear-gradient(
                to top,
                rgba(0, 0, 0, 0.7) 0%,
                rgba(0, 0, 0, 0.3) 50%,
                transparent 100%
              )
            `,
          }}
        />
      </div>

      {/* Text Overlay */}
      <div className="absolute inset-0 flex items-center justify-center">
        <div className="text-center text-white">
          <h1 className="text-5xl font-bold mb-4">Welcome to My Portfolio</h1>
          <p className="text-xl mb-6">I’m a developer passionate about creating stunning web experiences.</p>
          <Link
            to="/projects"
            className="inline-block bg-blue-600 text-white py-2 px-4 rounded hover:bg-blue-700 transition"
          >
            View My Work
          </Link>
        </div>
      </div>
    </div>
  );
}
